## Parsing Strings into Types

```xiom
pub interface FromStr {
  type Err;
  fn from_str(s: &Str) -> Result[Self, Self::Err];
}
```

### Implementing FromStr

```xiom
pub type Point = { x: Int; y: Int; }

pub type ParsePointError = enum {
  InvalidFormat,
  InvalidNumber,
}

impl FromStr for Point {
  type Err = ParsePointError;

  fn from_str(s: &Str) -> Result[Point, ParsePointError] {
    let parts = s.split(',');
    if parts.len() != 2 {
      return Err(ParsePointError::InvalidFormat);
    }
    let x = parts[0].trim().parse_int()?;
    let y = parts[1].trim().parse_int()?;
    return Ok(Point{ x: x, y: y });
  }
}

fn main() {
  let p: Point = "10, 20".parse().unwrap();
  // p = Point{ x: 10, y: 20 }
}
```

