### Config Parsing

```xiom
fn load_config(path: Str) -> Result[Config, ParseError] {
  let content = fs.read_to_str(path)?;
  for line in content.lines() {
    let (key, value) = line.split_once('=').unwrap();
    match key {
      "port" => config.port = value.trim().parse()?,
      "host" => config.host = value.trim(),
      _ => {},
    }
  }
  return Ok(config);
}
```

