pub type RgbColor = { r: Int; g: Int; b: Int; }

impl FromStr for RgbColor {
  type Err = Str;

  fn from_str(s: &Str) -> Result[RgbColor, Str] {
    let parts = s.split(',');
    if parts.len() != 3 { return Err("Expected r,g,b format"); }
    let r = parts[0].trim().parse_int();
    let g = parts[1].trim().parse_int();
    let b = parts[2].trim().parse_int();
    return Ok(RgbColor{ r: r, g: g, b: b });
  }
}

fn main() -> Int {
  let c: RgbColor = "100,150,200".parse().unwrap();
  return c.r + c.g + c.b;
}
